import { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 3;

function TaskSkeleton(): JSX.Element {
  return (
    <li className="task-board-item">
      <div className="task-board-skeleton-line" />
    </li>
  );
}

function TaskItem({ task }: { task: Task }): JSX.Element {
  return (
    <li className="task-board-item">
      <span className="task-board-item-title">{task.title}</span>
    </li>
  );
}

function renderListContent(tasks: Task[] | null): JSX.Element[] {
  if (tasks === null) {
    return Array.from({ length: SKELETON_COUNT }, (_, i) => <TaskSkeleton key={i} />);
  }
  return tasks.map((task) => <TaskItem key={task.id} task={task} />);
}

export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((data) => {
        setTasks(data);
      })
      .catch(() => {
        setTasks([]);
      });
  }, []);

  const isLoading = tasks === null;
  const isEmpty = tasks !== null && tasks.length === 0;
  const count = tasks !== null ? tasks.length : 0;

  return (
    <section className="task-board" aria-labelledby="task-board-heading">
      <header className="task-board-header">
        <h2 id="task-board-heading" className="task-board-heading">
          Tasks
        </h2>
        {!isLoading && (
          <span className="task-board-badge" aria-label={`${count} tasks`}>
            {count}
          </span>
        )}
      </header>

      <div className="task-board-filter-bar" role="search" aria-label="Filter tasks" />

      {isEmpty && <p className="task-board-empty">No tasks yet.</p>}

      {!isEmpty && (
        <ul className="task-board-list" aria-label="Tasks">
          {renderListContent(tasks)}
        </ul>
      )}
    </section>
  );
}
